-- ============================================
-- PostgreSQL Schema for Social Media Intelligence
-- ============================================
-- Note: UUIDs are generated by the application (JPA)
-- ============================================

-- ============================================
-- Table: users
-- ============================================
CREATE TABLE users
(
    id         UUID PRIMARY KEY,
    email      VARCHAR(255) NOT NULL UNIQUE,
    full_name  VARCHAR(255) NOT NULL,
    created_at TIMESTAMP    NOT NULL,
    updated_at TIMESTAMP    NOT NULL
);

-- Index on email for query performance
CREATE UNIQUE INDEX idx_user_email ON users (email);

-- ============================================
-- Table: user_credentials
-- ============================================
CREATE TABLE user_credentials
(
    id            UUID PRIMARY KEY,
    password_hash TEXT      NOT NULL,
    created_at    TIMESTAMP NOT NULL,
    updated_at    TIMESTAMP NOT NULL,

    -- Foreign key constraint
    CONSTRAINT fk_user_credentials_user
        FOREIGN KEY (id)
            REFERENCES users (id)
            ON DELETE CASCADE
);

-- ============================================
-- Table: social_accounts
-- ============================================
-- Social platform accounts linked to users. Access tokens are AES-GCM
-- encrypted by the application. Token timestamps are UTC.
CREATE TABLE social_accounts
(
    id                     UUID PRIMARY KEY,
    user_id                UUID          NOT NULL,
    platform               VARCHAR(32)   NOT NULL,
    platform_account_id    VARCHAR(255)  NOT NULL,
    username               VARCHAR(255),
    access_token_encrypted VARCHAR(2048) NOT NULL,
    token_expires_at       TIMESTAMP,
    token_issued_at        TIMESTAMP     NOT NULL,
    status                 VARCHAR(32)   NOT NULL,
    created_at             TIMESTAMP     NOT NULL,
    updated_at             TIMESTAMP     NOT NULL,

    CONSTRAINT fk_social_accounts_user
        FOREIGN KEY (user_id)
            REFERENCES users (id)
            ON DELETE CASCADE,

    CONSTRAINT uk_social_accounts_user_platform_account
        UNIQUE (user_id, platform, platform_account_id)
);

CREATE INDEX idx_social_accounts_user ON social_accounts (user_id);

-- ============================================
-- Trigger: Auto-update updated_at timestamp
-- ============================================

-- Function to update updated_at column
CREATE
    OR REPLACE FUNCTION update_updated_at_column()
    RETURNS TRIGGER AS
$$
BEGIN
    NEW.updated_at
        = CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$
    LANGUAGE plpgsql;

-- Trigger for users table
CREATE TRIGGER update_users_updated_at
    BEFORE UPDATE
    ON users
    FOR EACH ROW
EXECUTE FUNCTION update_updated_at_column();

-- Trigger for user_credentials table
CREATE TRIGGER update_user_credentials_updated_at
    BEFORE UPDATE
    ON user_credentials
    FOR EACH ROW
EXECUTE FUNCTION update_updated_at_column();

-- Trigger for social_accounts table
CREATE TRIGGER update_social_accounts_updated_at
    BEFORE UPDATE
    ON social_accounts
    FOR EACH ROW
EXECUTE FUNCTION update_updated_at_column();
